@@ -0,0 +1,67 @@
+/**
+ * Prints the decidability probe's result. Counts, never percentages, and never the word
+ * "accuracy" — there is no full-diff baseline to be accurate against.
+ */
+
+import { controlDiagnostics, DEFECT_CLASSES, FIXTURES, PER_CLASS, runArm, summarize, type ArmId } from '../src/probe.ts';
+
+const ARMS: readonly ArmId[] = ['metadata-only', 'metadata-plus-contract-recomputation', 'shuffled-metadata'];
+
+const pad = (text: string, width: number): string => text.padEnd(width, ' ');
+
+const main = (): void => {
+  process.stdout.write('\nDECIDABILITY PROBE — B3 / D7 / docs/08 II.4\n');
+  process.stdout.write(`fixtures: ${FIXTURES.length} (${PER_CLASS} per class x ${DEFECT_CLASSES.length} classes)\n`);
+  process.stdout.write('receiver: deterministic rules (src/decide.ts), fixed before any fixture was scored\n');
+  process.stdout.write('arm 4 (full diff): NOT IMPLEMENTED — no judge that reads the change exists here.\n');
+  process.stdout.write('                   There is therefore NO BASELINE, and nothing below is an accuracy.\n\n');
+
+  for (const arm of ARMS) {
+    const results = summarize(runArm(arm));
+    process.stdout.write(`${arm}\n`);
+    process.stdout.write(`  ${pad('class', 8)}${pad('n', 4)}${pad('rejected', 10)}${pad('as ground truth', 17)}rules that fired\n`);
+    for (const row of results) {
+      const flag = row.defectClass === 'D-d' ? '  <- must NOT be caught' : '';
+      process.stdout.write(
+        `  ${pad(row.defectClass, 8)}${pad(String(row.n), 4)}${pad(String(row.rejected), 10)}${pad(`${row.correct}/${row.n}`, 17)}${row.rulesFired.join(', ') || '-'}${flag}\n`,
+      );
+    }
+    process.stdout.write('\n');
+  }
+
+  const metadataOnly = summarize(runArm('metadata-only'));
+  const withContracts = summarize(runArm('metadata-plus-contract-recomputation'));
+  const shuffled = summarize(runArm('shuffled-metadata'));
+
+  const caught = (rows: readonly { defectClass: string; rejected: number }[], cls: string): number =>
+    rows.find((row) => row.defectClass === cls)?.rejected ?? 0;
+
+  process.stdout.write('READING\n');
+  process.stdout.write(
+    `  Reachable from metadata alone: D-b (${caught(metadataOnly, 'D-b')}/${PER_CLASS}), ` +
+      `D-c (${caught(metadataOnly, 'D-c')}/${PER_CLASS}), D-e (${caught(metadataOnly, 'D-e')}/${PER_CLASS}).\n`,
+  );
+  process.stdout.write(
+    `  NOT reachable from metadata alone: D-a (${caught(metadataOnly, 'D-a')}/${PER_CLASS}). ` +
+      `It becomes reachable (${caught(withContracts, 'D-a')}/${PER_CLASS}) only when a party holding the change\n` +
+      '  re-derives the altered contract set. That party read the diff. The bill moved from the receiver\n' +
+      "  to the verifier's toolchain; it was not removed.\n",
+  );
+  process.stdout.write(
+    `  Must not be caught: D-d (${caught(metadataOnly, 'D-d')}/${PER_CLASS} metadata-only, ` +
+      `${caught(withContracts, 'D-d')}/${PER_CLASS} with contract recomputation).\n`,
+  );
+  const control = controlDiagnostics();
+  process.stdout.write(
+    `  Form-matched control: shuffled metadata rejects ${shuffled.reduce((total, row) => total + row.rejected, 0)}` +
+      ` of ${FIXTURES.length} and scores ${shuffled.reduce((total, row) => total + row.correct, 0)}/${FIXTURES.length}\n` +
+      '  against ground truth. Do NOT read that as "the control nearly matches the real arm" — with a\n' +
+      '  class-balanced 36-fixture set it is mostly the base rate. What the control is for is the next line.\n' +
+      `  Of ${control.n} shuffled decisions, ${control.agreesWithDonor} follow the DONOR's decision and ` +
+      `${control.agreesWithOwn} follow the fixture's own\n` +
+      `  (${control.fixedPoints} fixture(s) were left with their own input by the shuffle). The rules are reading\n` +
+      '  the contents of the metadata, not the fact that structured metadata arrived.\n',
+  );
+};
+
+main();
diff --git a/poc/src/marks.ts b/poc/src/marks.ts
