index 0000000..584ad07
--- /dev/null
+++ b/poc/src/marks.ts
@@ -0,0 +1,62 @@
+/**
+ * D13 / docs/08 II.0 — the evidence/testimony split, expressed in the type system.
+ *
+ * The point of this file is N2: "No verifier conclusion may take a `T` field as input."
+ * That rule is enforced here by making `Testimony<T>` structurally un-assignable to any
+ * position that asks for `Evidence<T>`. A conclusion function that accepts `Evidence<X>`
+ * cannot be handed a `Testimony<X>` without a cast, and `tsc` is the check. See
+ * test/marks.type-negative.ts for the assertions that fail the build if that stops
+ * being true.
+ */
+
+export type Mark = 'E' | 'E*' | 'T';
+
+/** A pin named inside the record that carries the E* field it conditions (II.0). */
+export interface PinRef {
+  readonly name: string;
+  readonly digest: string;
+}
+
+/**
+ * `E` — re-derivable by a verifier that does not trust the asserter, by recomputation
+ * or by a signature chain to an anchor outside the asserter's control.
+ */
+export interface Evidence<T> {
+  readonly mark: 'E';
+  readonly value: T;
+}
+
+/**
+ * `E*` — re-derivable *only* if every pin named here is present and resolvable.
+ * A missing pin demotes the field to `T`. No default, no fallback (II.0).
+ */
+export interface ConditionalEvidence<T> {
+  readonly mark: 'E*';
+  readonly value: T;
+  readonly pins: readonly PinRef[];
+}
+
+/** `T` — testimony. Carried (N4), attributable, never an input to a conclusion (N2). */
+export interface Testimony<T> {
+  readonly mark: 'T';
+  readonly value: T;
+}
+
+export type Marked<T> = Evidence<T> | ConditionalEvidence<T> | Testimony<T>;
+
+export const evidence = <T>(value: T): Evidence<T> => ({ mark: 'E', value });
+
+export const conditionalEvidence = <T>(value: T, pins: readonly PinRef[]): ConditionalEvidence<T> => ({
+  mark: 'E*',
+  value,
+  pins,
+});
+
+export const testimony = <T>(value: T): Testimony<T> => ({ mark: 'T', value });
+
+/**
+ * N3 — a field's mark belongs to the schema, not to the instance. Demotion is the one
+ * legal transition and it only ever runs one way (E* -> T, on a missing pin). There is
+ * deliberately no `promote`.
+ */
+export const demoteToTestimony = <T>(field: ConditionalEvidence<T>): Testimony<T> => testimony(field.value);
