+/**
+ * argv parsing for the two party processes. Deliberately minimal, and deliberately the
+ * only channel by which a party learns anything about the world other than the socket:
+ * owner-b is never told where owner-a's store is, because the point of the testbed is
+ * that it could not use it if it wanted to.
+ */
+
+export interface PartyArgs {
+  readonly scenario: string;
+  readonly socket: string;
+  readonly store: string;
+  readonly nowMs: number;
+  readonly deadlineMs: number;
+}
+
+export const parseArgs = (argv: readonly string[]): PartyArgs => {
+  const values = new Map<string, string>();
+  for (let index = 0; index < argv.length; index += 2) {
+    const flag = argv[index];
+    const value = argv[index + 1];
+    if (flag === undefined || !flag.startsWith('--') || value === undefined) {
+      throw new Error(`bad argv near position ${index}: expected '--flag value', saw ${JSON.stringify(argv.slice(index, index + 2))}`);
+    }
+    values.set(flag.slice(2), value);
+  }
+
+  const required = (name: string): string => {
+    const value = values.get(name);
+    if (value === undefined) throw new Error(`missing required argument --${name}`);
+    return value;
+  };
+
+  const integer = (name: string, fallback: number): number => {
+    const raw = values.get(name);
+    if (raw === undefined) return fallback;
+    const parsed = Number.parseInt(raw, 10);
+    if (!Number.isSafeInteger(parsed)) throw new Error(`--${name} must be an integer, saw '${raw}'`);
+    return parsed;
+  };
+
+  return {
+    scenario: required('scenario'),
+    socket: required('socket'),
+    store: required('store'),
+    nowMs: integer('now', 1_760_000_000_000),
+    deadlineMs: integer('deadline', 3000),
+  };
+};
diff --git a/poc/src/party/owner-a.ts b/poc/src/party/owner-a.ts
new file mode 100644
index 0000000..78a8814
--- /dev/null
+++ b/poc/src/party/owner-a.ts
@@ -0,0 +1,36 @@
+/**
+ * Owner A's process. Session 1: declares, works, emits.
+ *
+ * It knows exactly two things about the outside world: the socket path, and its own store
+ * root. It is never told where owner B's store is. Whether it is honest depends only on
+ * --scenario; every scenario is scripted in adversaries.ts.
+ */
+
+import { connectAndSend } from '../channel.ts';
+import { type ScenarioId, SCENARIOS, defaultContext, scenarioConnects, scenarioLines } from '../adversaries.ts';
+import { AppendOnlyStore } from '../store.ts';
+import { parseArgs } from './args.ts';
+
+const main = async (): Promise<void> => {
+  const args = parseArgs(process.argv.slice(2));
+  if (!(SCENARIOS as readonly string[]).includes(args.scenario)) {
+    throw new Error(`unknown scenario '${args.scenario}'; known: ${SCENARIOS.join(', ')}`);
+  }
+  const scenario = args.scenario as ScenarioId;
+
+  const store = new AppendOnlyStore(args.store);
+  const lines = scenarioLines(scenario, defaultContext(args.nowMs));
+  // Stored raw, not parsed: the a4-garbage scenario emits lines that are deliberately not
+  // JSON, and an emitter that could not send them would be testing a politer adversary.
+  for (const line of lines) store.append('emitted', line);
+
+  if (!scenarioConnects(scenario)) {
+    process.stdout.write(`owner-a: scenario '${scenario}' never opens the channel\n`);
+    return;
+  }
+
+  await connectAndSend(args.socket, lines);
+  process.stdout.write(`owner-a: scenario '${scenario}' sent ${lines.length} line(s)\n`);
+};
+
+await main();
