+++ b/poc/src/report.ts
@@ -0,0 +1,49 @@
+/** The one thing owner-b writes to stdout, and the only thing the harness reads back. */
+
+import type { BudgetState, ClaimStanding } from './reader.ts';
+import type { Conclusion } from './verifier.ts';
+
+export const REPORT_PREFIX = '##REPORT##';
+
+export interface ReceiverReport {
+  readonly scenario: string;
+  readonly linesReceived: number;
+  readonly unparseable: number;
+  readonly foreignExtension: number;
+  readonly decodeFailures: readonly { readonly field: string; readonly reason: string }[];
+  readonly recordsAccepted: Readonly<Record<string, number>>;
+  readonly conclusions: readonly Conclusion[];
+  readonly claimStandings: readonly ClaimStanding[];
+  readonly budget: readonly BudgetState[];
+  readonly contention: readonly string[];
+  readonly decision: 'ACCEPT' | 'REJECT' | 'NO_DECISION';
+  readonly decisionReasons: readonly string[];
+  /**
+   * ChangeSets that arrived with no Completion binding them to a Claim. docs/08 II.4 hands
+   * the decision "the Claim/Completion pair the change belongs to", so for these the
+   * claim-side rules (R4/R5/R6) do not run at all.
+   */
+  readonly unboundChangeSets: number;
+  /**
+   * L13 — "no blocking, no retries, no waiting on a reply that is not coming." True means
+   * the receiver hit its deadline instead of the counterparty hanging up.
+   */
+  readonly timedOut: boolean;
+  readonly counterpartyConnected: boolean;
+  readonly elapsedMs: number;
+  readonly publishedPolicy: Readonly<Record<string, number | boolean>>;
+  /** Distinct signing keys seen asserting records. Rebranding shows up here. */
+  readonly distinctKeyIds: readonly string[];
+  readonly storeRoot: string;
+  readonly storeEntries: number;
+}
+
+export const parseReport = (stdout: string): ReceiverReport => {
+  const line = stdout
+    .split('\n')
+    .find((candidate) => candidate.startsWith(REPORT_PREFIX));
+  if (line === undefined) {
+    throw new Error(`owner-b produced no ${REPORT_PREFIX} line. stdout was:\n${stdout}`);
+  }
+  return JSON.parse(line.slice(REPORT_PREFIX.length)) as ReceiverReport;
+};
diff --git a/poc/src/seam-stub.ts b/poc/src/seam-stub.ts
new file mode 100644
index 0000000..8550257
--- /dev/null
+++ b/poc/src/seam-stub.ts
@@ -0,0 +1,47 @@
+/**
+ * STUB. This file stands in for Track A and must not survive D4/D5.
+ *
+ * docs/08 II.5: "`NodeRef` = file path + line range, opaque, marked a stub for D4/D5.
+ * `covers()` = path-prefix containment. This stand-in must not appear in any published
+ * conclusion."
+ *
+ * It is the only file in the testbed permitted to look inside a `NodeId`, and it does so
+ * through the deliberately ugly accessor name. Everything else takes `CoversPredicate`
+ * as an argument.
+ */
+
+import { type CoversPredicate, type NodeRef, nodeIdFromWire, schemesMatch, unsafeReadNodeIdForTrackAStubOnly } from './seam.ts';
+
+/** The stub's own addressing scheme. Never to be read as a proposal for D4. */
+export const STUB_SCHEME = 'vibehub.invalid/poc/stub/path-prefix/v0';
+
+/**
+ * Path-prefix containment, with a wildcard suffix. `src/` covers `src/auth/session.ts`;
+ * `src/auth/session.ts` covers itself and nothing else; `*` covers everything.
+ */
+export const pathPrefixCovers: CoversPredicate = (outer, inner) => {
+  if (!schemesMatch(outer, inner)) return false;
+
+  const outerPath = unsafeReadNodeIdForTrackAStubOnly(outer.id);
+  const innerPath = unsafeReadNodeIdForTrackAStubOnly(inner.id);
+
+  if (outerPath === '*') return true;
+  if (outerPath === innerPath) return true;
+  return innerPath.startsWith(outerPath.endsWith('/') ? outerPath : `${outerPath}/`);
+};
+
+/**
+ * L12's breadth test needs to know whether a subject is a wildcard or a whole scheme.
+ * That is also structural knowledge about an identifier, so it lives here too.
+ */
+export const isBreadthSubject = (ref: NodeRef): boolean => {
+  const path = unsafeReadNodeIdForTrackAStubOnly(ref.id);
+  return path === '*' || path.endsWith('/') || path.includes('*');
+};
+
+/**
+ * Minting a NodeRef means choosing an addressing scheme, which is D4's decision and not
+ * Track B's. So it happens here, in the file that is supposed to be deleted, and nowhere
+ * else — see test/seam-lint.test.ts.
+ */
+export const stubRef = (path: string): NodeRef => ({ scheme: STUB_SCHEME, id: nodeIdFromWire(path) });
diff --git a/poc/src/seam.ts b/poc/src/seam.ts
