+++ b/poc/src/seam.ts
@@ -0,0 +1,63 @@
+/**
+ * The Track A seam. docs/08 II.2:
+ *
+ *   "Track B MUST NOT parse, destructure, compare structurally, or order these."
+ *   "Any Track B code that branches on the internal structure of a `NodeRef` is a seam
+ *    violation and should be caught by a lint, not by a review."
+ *
+ * So `NodeId` here is not a string. Its payload hangs off a module-private symbol, which
+ * means no Track B module can call a string method on it, slice it, or sort by it without
+ * first importing one of the three accessors below. test/seam-lint.test.ts asserts which
+ * files import which accessor; that is the lint.
+ *
+ * The single comparison Track B may make unaided is byte equality (`nodeIdEquals`).
+ * Containment — `covers(a, b)` — is S2 in docs/08 II.6: a predicate Track A owes Track B
+ * and does not currently promise. This testbed injects a stand-in for it (seam-stub.ts)
+ * rather than computing it, because computing it here would be the seam violation.
+ */
+
+const RAW = Symbol('vibehub.poc.node-id.raw');
+
+export interface NodeId {
+  readonly [RAW]: string;
+}
+
+/** WIRE ONLY. Imported by wire.ts and nothing else — see test/seam-lint.test.ts. */
+export const nodeIdFromWire = (encoded: string): NodeId => ({ [RAW]: encoded });
+
+/** WIRE ONLY. Imported by wire.ts and nothing else — see test/seam-lint.test.ts. */
+export const nodeIdToWire = (id: NodeId): string => id[RAW];
+
+/**
+ * TRACK A STAND-IN ONLY. The only legitimate importer is seam-stub.ts, which exists to
+ * be deleted the moment D4/D5 are answered. Any other importer is a seam violation.
+ */
+export const unsafeReadNodeIdForTrackAStubOnly = (id: NodeId): string => id[RAW];
+
+/** Byte equality. The only comparison Track B can make on its own (docs/08 II.2). */
+export const nodeIdEquals = (a: NodeId, b: NodeId): boolean => a[RAW] === b[RAW];
+
+/**
+ * D4/D5 — Track A's decision, not ours. `epoch` is optional precisely so that either
+ * answer to D5 survives: it is the content hash under "names over immutable hashes",
+ * and absent under "stable ids".
+ */
+export interface NodeRef {
+  readonly scheme: string;
+  readonly id: NodeId;
+  readonly epoch?: string;
+}
+
+export interface SessionRef {
+  readonly scheme: string;
+  readonly id: NodeId;
+}
+
+/**
+ * S2. Track A owes Track B a remotely-evaluable `covers(a, b) -> bool` over NodeRefs.
+ * Injected everywhere it is needed so that no Track B module ever has a default.
+ */
+export type CoversPredicate = (outer: NodeRef, inner: NodeRef) => boolean;
+
+/** Different addressing schemes are not comparable, whatever the ids look like. */
+export const schemesMatch = (a: NodeRef, b: NodeRef): boolean => a.scheme === b.scheme;
