--- /dev/null
+++ b/poc/src/store.ts
@@ -0,0 +1,79 @@
+/**
+ * One party's private, append-only log. There is one of these per process and neither
+ * process is given the other's root.
+ *
+ * WHAT THIS DOES AND DOES NOT GUARANTEE — read before quoting the testbed's isolation.
+ *
+ *   It guarantees, and test/store.test.ts checks: no code path in this testbed can read
+ *   or write outside the root it was constructed with. `resolve()` throws on any path
+ *   that escapes, including via `..` and via symlink-free absolute paths.
+ *
+ *   It does NOT guarantee OS-level isolation. Both party processes run as the same uid on
+ *   the same machine. A party that wanted the other's log could open it with plain `fs`
+ *   and this class would never know. The isolation here is structural — separate
+ *   processes, separate address spaces, separate roots, and neither root passed to the
+ *   other — not enforced by the operating system. Saying otherwise would be the exact
+ *   kind of claim docs/03 W3 exists to stop us making.
+ */
+
+import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';
+import { isAbsolute, resolve, sep } from 'node:path';
+
+export class StoreBoundaryError extends Error {
+  constructor(attempted: string, root: string) {
+    super(`store access refused: '${attempted}' resolves outside this party's root '${root}'`);
+    this.name = 'StoreBoundaryError';
+  }
+}
+
+export interface LogEntry {
+  readonly seq: number;
+  readonly direction: 'emitted' | 'received';
+  readonly payload: unknown;
+}
+
+export class AppendOnlyStore {
+  readonly #root: string;
+  readonly #logPath: string;
+  #seq = 0;
+
+  constructor(root: string) {
+    if (!isAbsolute(root)) throw new Error(`store root must be absolute, saw '${root}'`);
+    this.#root = resolve(root);
+    mkdirSync(this.#root, { recursive: true, mode: 0o700 });
+    this.#logPath = this.resolveInRoot('log.ndjson');
+  }
+
+  get root(): string {
+    return this.#root;
+  }
+
+  /** The confinement check. Every filesystem path this class touches goes through it. */
+  resolveInRoot(name: string): string {
+    const candidate = resolve(this.#root, name);
+    if (candidate !== this.#root && !candidate.startsWith(this.#root + sep)) {
+      throw new StoreBoundaryError(name, this.#root);
+    }
+    return candidate;
+  }
+
+  append(direction: LogEntry['direction'], payload: unknown): LogEntry {
+    const entry: LogEntry = { seq: this.#seq++, direction, payload };
+    appendFileSync(this.#logPath, `${JSON.stringify(entry)}\n`, { mode: 0o600 });
+    return entry;
+  }
+
+  read(): readonly LogEntry[] {
+    let raw: string;
+    try {
+      raw = readFileSync(this.#logPath, 'utf8');
+    } catch (error) {
+      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
+      throw error;
+    }
+    return raw
+      .split('\n')
+      .filter((line) => line.length > 0)
+      .map((line) => JSON.parse(line) as LogEntry);
+  }
+}
