+/**
+ * The verifier's own resources: what a recomputation actually returns.
+ *
+ * SIMULATED. Nothing here runs a test suite, a build or a typechecker. `WORLD_FACTS` is a
+ * lookup table standing in for "the check, re-run by the verifier on its own toolchain."
+ * That is enough to exercise docs/08 II.1 step 3 — assert vs recompute vs REFUTE — and it
+ * is NOT enough to say anything about reproducible builds, which docs/10 A3 calls the
+ * heaviest tax in the design. Any statement of the form "the testbed shows recomputation
+ * catches X" means "the plumbing routes X to REFUTED", nothing more.
+ *
+ * The table lives on the verifying side and never travels over the channel. That is the
+ * point: a verifier concludes from what it can re-derive itself, not from what it was told.
+ */
+
+import type { PinRef } from './marks.ts';
+import type { PinResolver, RecomputeOutcome, RecomputeRequest, Toolchain } from './verifier.ts';
+
+export interface WorldFact {
+  readonly checkId: string;
+  readonly inputDigest: string;
+  readonly trueOutputDigest: string;
+}
+
+/** The change session 1 actually makes, and the digest that names it. */
+export const CHANGE_INPUT_DIGEST = 'input:session-1-auth-refresh';
+
+export const TRUE_TEST_RESULT = 'out:unit-tests:pass:41';
+export const TRUE_BUILD_RESULT = 'out:build:ok';
+/** What a typechecker holding the diff says the altered contract set really is. */
+export const TRUE_ALTERED_CONTRACTS = 'out:contracts-altered:[SessionStore.refresh]';
+
+export const WORLD_FACTS: readonly WorldFact[] = [
+  { checkId: 'check:unit-tests', inputDigest: CHANGE_INPUT_DIGEST, trueOutputDigest: TRUE_TEST_RESULT },
+  { checkId: 'check:build', inputDigest: CHANGE_INPUT_DIGEST, trueOutputDigest: TRUE_BUILD_RESULT },
+  { checkId: 'check:contracts-altered', inputDigest: CHANGE_INPUT_DIGEST, trueOutputDigest: TRUE_ALTERED_CONTRACTS },
+];
+
+export const makeFixtureToolchain = (id: string, facts: readonly WorldFact[] = WORLD_FACTS): Toolchain => ({
+  id,
+  recompute(request: RecomputeRequest): RecomputeOutcome {
+    const fact = facts.find((f) => f.checkId === request.checkId && f.inputDigest === request.inputDigest);
+    if (fact === undefined) {
+      return {
+        supported: false,
+        reason: `this toolchain has no procedure for check '${request.checkId}' on input '${request.inputDigest}'`,
+      };
+    }
+    return { supported: true, observed: fact.trueOutputDigest };
+  },
+});
+
+/** Pins the verifier can actually resolve. Anything else demotes its E* field to T. */
+export const RESOLVABLE_PINS: readonly string[] = ['toolchain:node-22', 'env:linux-x64', 'corpus:auth-fixtures'];
+
+export const makePinResolver = (available: readonly string[] = RESOLVABLE_PINS): PinResolver =>
+  (pin: PinRef) => available.includes(pin.name);
+
+export const pin = (name: string): PinRef => ({ name, digest: `digest-of:${name}` });
+
+export const RESOLVABLE_PIN_SET: readonly PinRef[] = RESOLVABLE_PINS.map(pin);
