+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+
+import { CanonicalizationError, canonicalize, digestOf } from '../src/canonical.ts';
+
+test('object keys are sorted by UTF-16 code unit, whatever order they were written in', () => {
+  assert.equal(canonicalize({ b: 1, a: 2 }), '{"a":2,"b":1}');
+  assert.equal(canonicalize({ a: 2, b: 1 }), canonicalize({ b: 1, a: 2 }));
+  // Uppercase sorts before lowercase under code-unit ordering, unlike locale collation.
+  assert.equal(canonicalize({ a: 1, B: 2 }), '{"B":2,"a":1}');
+});
+
+test('nested objects and arrays canonicalize recursively; array order is preserved', () => {
+  assert.equal(canonicalize({ z: [{ b: 1, a: 2 }], a: null }), '{"a":null,"z":[{"a":2,"b":1}]}');
+});
+
+test('two independently-built objects with the same content produce identical bytes', () => {
+  const first = { subject: 'x', statements: [{ checkId: 'c', mark: 'E' }], canonicalization: 'u' };
+  const second = { canonicalization: 'u', statements: [{ mark: 'E', checkId: 'c' }], subject: 'x' };
+  assert.equal(canonicalize(first), canonicalize(second));
+  assert.equal(digestOf(first), digestOf(second));
+});
+
+test('non-integer numbers are refused rather than serialized differently from RFC 8785', () => {
+  assert.throws(() => canonicalize({ n: 1.5 }), CanonicalizationError);
+  assert.throws(() => canonicalize({ n: Number.NaN }), CanonicalizationError);
+  assert.throws(() => canonicalize({ n: Number.POSITIVE_INFINITY }), CanonicalizationError);
+  assert.throws(() => canonicalize({ n: 2 ** 53 }), CanonicalizationError);
+});
+
+test('negative zero is refused: JSON.stringify(-0) is "0" and the ambiguity is not worth carrying', () => {
+  assert.throws(() => canonicalize({ n: -0 }), CanonicalizationError);
+});
+
+test('undefined has no canonical form and is refused loudly, not dropped', () => {
+  assert.throws(() => canonicalize({ a: undefined } as never), CanonicalizationError);
+});
+
+test('the error names the path, so a failure in a nested record is findable', () => {
+  assert.throws(
+    () => canonicalize({ outer: { inner: [0, 1.5] } }),
+    (error: unknown) => error instanceof CanonicalizationError && error.message.includes('$.outer.inner[1]'),
+  );
+});
+
+test('digests are algorithm-prefixed, so they can be migrated', () => {
+  assert.match(digestOf({ a: 1 }), /^blake2b512:[0-9a-f]{128}$/);
+});
