+import { buildActor, buildAttestation, pinnedStatement, recomputableStatement, reportStatement } from '../src/records.ts';
+import type { Actor, Attestation, Statement } from '../src/schema.ts';
+import { partyKeysFromSeed, selfSignedAnchor, type PartyKeys } from '../src/signing.ts';
+import type { Conclusion, VerifierConfig } from '../src/verifier.ts';
+import { makeFixtureToolchain, makePinResolver, pin, RESOLVABLE_PIN_SET, type WorldFact } from '../src/world.ts';
+import { stubAnchorResolver } from '../src/signing.ts';
+
+export const TEST_ACTOR_ID = 'https://test.invalid/agents/a';
+
+export const testKeys = (seed = 'test-actor'): PartyKeys => partyKeysFromSeed(seed);
+
+export const testCard = (keys: PartyKeys = testKeys(), actorId = TEST_ACTOR_ID): Actor =>
+  buildActor({
+    actorId,
+    keys,
+    anchor: selfSignedAnchor(keys),
+    providerOrg: 'test',
+    providerOrgPins: [],
+    modelRef: 'PLACEHOLDER',
+    harnessRef: 'PLACEHOLDER',
+    toolsDigest: 'digest:tools',
+    toolsDigestPins: [],
+    humanPrincipal: null,
+    compositionEpoch: 0,
+    compositionEpochPins: [],
+  });
+
+export const testAttestation = (statements: readonly Statement[], keys: PartyKeys = testKeys(), actorId = TEST_ACTOR_ID): Attestation =>
+  buildAttestation({
+    actorId,
+    keys,
+    subject: 'changeset:test',
+    predicateType: 'https://test.invalid/predicates/v0',
+    statements,
+  });
+
+export const okRecomputable = (checkId: string, index: number): Statement =>
+  recomputableStatement({
+    checkId,
+    procedureRef: 'procedure:test',
+    inputDigest: `input:${index}`,
+    expectedOutputDigest: `out:${index}`,
+  });
+
+export const okPinned = (checkId: string, index: number): Statement =>
+  pinnedStatement({
+    checkId,
+    pins: RESOLVABLE_PIN_SET,
+    toolchainDigest: 'digest:toolchain',
+    envDigest: 'digest:env',
+    inputDigest: `input:${index}`,
+    result: `out:${index}`,
+    logDigest: `digest:log:${index}`,
+  });
+
+export const unresolvablePinned = (checkId: string, index: number): Statement =>
+  pinnedStatement({
+    checkId,
+    pins: [pin('toolchain:nobody-elses')],
+    toolchainDigest: 'digest:toolchain',
+    envDigest: 'digest:env',
+    inputDigest: `input:${index}`,
+    result: `out:${index}`,
+    logDigest: `digest:log:${index}`,
+  });
+
+export const report = (checkId: string, text: string): Statement => reportStatement(checkId, text);
+
+export const factsFor = (count: number): readonly WorldFact[] =>
+  Array.from({ length: count }, (_unused, index) => ({
+    checkId: `check:${index}`,
+    inputDigest: `input:${index}`,
+    trueOutputDigest: `out:${index}`,
+  }));
+
+/** Spot-check rate 1 so E* sampling never adds noise to an assertion about the procedure. */
+export const testConfig = (facts: readonly WorldFact[], spotCheckRate = 1): VerifierConfig => ({
+  publishedSpotCheckRate: spotCheckRate,
+  spotCheckSalt: 'test/v0',
+  toolchain: makeFixtureToolchain('test/toolchain', facts),
+  resolvePin: makePinResolver(),
+  resolveAnchor: stubAnchorResolver,
+});
+
+/**
+ * A conclusion "flip" means the procedure reached a different conclusion ABOUT A CHECK.
+ * Attestation ids and canonical digests move whenever any byte changes, including in a
+ * testimony field, so comparing raw conclusion objects would report a flip for every
+ * plant and measure nothing.
+ */
+export const conclusionSignature = (conclusions: readonly Conclusion[]): string =>
+  conclusions
+    .map((conclusion) => {
+      switch (conclusion.kind) {
+        case 'ATTRIBUTED':
+          return `ATTRIBUTED:${conclusion.actorId}:${conclusion.anonymous}`;
+        case 'REFUTED':
+          return `REFUTED:${conclusion.checkId}:${conclusion.asserted}:${conclusion.observed}`;
+        case 'UNVERIFIABLE':
+          return `UNVERIFIABLE:${conclusion.scope}:${conclusion.reason}`;
+        case 'PINS_MISSING':
+          return `PINS_MISSING:${conclusion.checkId}:${conclusion.missing.join(',')}`;
+        default:
+          return `${conclusion.kind}:${conclusion.checkId}`;
+      }
+    })
+    .sort()
+    .join('|');
