+/**
+ * D13, checked by the COMPILER rather than at runtime.
+ *
+ * This file contains no assertions and is never executed. Its job is to fail `tsc` if
+ * testimony ever becomes assignable to an evidence position. Each `@ts-expect-error` is an
+ * assertion in the other direction: if the error stops occurring, the build breaks and N2
+ * has silently been lost.
+ *
+ * `npm run typecheck` is therefore part of the D13 test suite, not a separate concern.
+ */
+
+import { conditionalEvidence, evidence, testimony, type ConditionalEvidence, type Evidence, type Testimony } from '../src/marks.ts';
+
+/** Stands in for any verifier conclusion: it takes evidence and nothing else (N2). */
+const concludeFromEvidence = (_field: Evidence<string>): void => {};
+const concludeFromConditionalEvidence = (_field: ConditionalEvidence<string>): void => {};
+
+concludeFromEvidence(evidence('a re-derivable fact'));
+concludeFromConditionalEvidence(conditionalEvidence('a pinned fact', [{ name: 'toolchain', digest: 'd' }]));
+
+// @ts-expect-error N2: testimony may never be an input to a conclusion.
+concludeFromEvidence(testimony('the agent says the tests passed'));
+
+// @ts-expect-error N2: E* is not E. A pinned fact is only evidence if its pins resolve.
+concludeFromEvidence(conditionalEvidence('a pinned fact', []));
+
+// @ts-expect-error N2: testimony is not conditional evidence either.
+concludeFromConditionalEvidence(testimony('the agent says the build was clean'));
+
+// @ts-expect-error N3: a mark cannot be asserted by the instance.
+const forged: Evidence<string> = { mark: 'T', value: 'promoted at runtime' };
+
+// @ts-expect-error N3, from the other side.
+const forgedTestimony: Testimony<string> = { mark: 'E', value: 'demoted at runtime' };
+
+// Referenced so `noUnusedLocals` does not hide the two assertions above.
+export const negatives = { forged, forgedTestimony };
