+/**
+ * The decidability probe's findings, asserted so they cannot drift silently.
+ *
+ * These are assertions about WHICH DEFECT CLASSES ARE STRUCTURALLY REACHABLE, not about
+ * accuracy. There is no full-diff arm, so there is no accuracy to assert.
+ */
+
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+
+import { controlDiagnostics, FIXTURES, PER_CLASS, runArm, summarize, type DefectClass } from '../src/probe.ts';
+
+const rejectedIn = (arm: 'metadata-only' | 'metadata-plus-contract-recomputation' | 'shuffled-metadata', defectClass: DefectClass): number =>
+  summarize(runArm(arm)).find((row) => row.defectClass === defectClass)?.rejected ?? -1;
+
+test('the fixture set is class-balanced', () => {
+  assert.equal(FIXTURES.length, PER_CLASS * 6);
+});
+
+test('metadata alone decides D-b, D-c and D-e, and accepts the clean changes', () => {
+  assert.equal(rejectedIn('metadata-only', 'D-b'), PER_CLASS, 'a fabricated test result is refuted by recomputation');
+  assert.equal(rejectedIn('metadata-only', 'D-c'), PER_CLASS, 'writes outside the claim subject are visible in metadata');
+  assert.equal(rejectedIn('metadata-only', 'D-e'), PER_CLASS, 'an E* with unresolvable pins demotes and is caught');
+  assert.equal(rejectedIn('metadata-only', 'clean'), 0);
+});
+
+test('THE FINDING — metadata alone cannot decide D-a: a metadata field lying about content it cannot see', () => {
+  assert.equal(rejectedIn('metadata-only', 'D-a'), 0);
+});
+
+test('D-a becomes decidable only once someone holding the change re-derives the contract set', () => {
+  assert.equal(rejectedIn('metadata-plus-contract-recomputation', 'D-a'), PER_CLASS);
+});
+
+test('D-d — the class this layer cannot serve — is not caught in any arm, which is correct', () => {
+  assert.equal(rejectedIn('metadata-only', 'D-d'), 0);
+  assert.equal(rejectedIn('metadata-plus-contract-recomputation', 'D-d'), 0);
+});
+
+test('the form-matched control shows the rules read the metadata\'s contents, not its presence', () => {
+  const control = controlDiagnostics();
+  assert.equal(control.n, FIXTURES.length);
+  assert.equal(
+    control.agreesWithDonor,
+    FIXTURES.length,
+    'every shuffled decision follows the donor, so the arm is responding to contents',
+  );
+  assert.ok(control.agreesWithOwn < FIXTURES.length, 'and not merely to the fact that structured metadata arrived');
+});
+
+test('the full-diff arm refuses to be run rather than being approximated', () => {
+  assert.throws(() => runArm('full-diff'), /NOT IMPLEMENTED/);
+});
