+import { runScenario } from '../scenarios/run.ts';
+
+for (const expectation of EXPECTATIONS) {
+  test(`${expectation.scenario} [${expectation.adversary}] behaves as pre-registered (${expectation.designOutcome})`, async () => {
+    const result = await runScenario(expectation);
+    assert.equal(result.ownerAExit, 0, `owner-a exited ${result.ownerAExit}: ${result.ownerAStderr}`);
+    assert.equal(result.ownerBExit, 0, `owner-b exited ${result.ownerBExit}: ${result.ownerBStderr}`);
