+/**
+ * docs/08 II.2: "Any Track B code that branches on the internal structure of a `NodeRef`
+ * is a seam violation and should be caught by a lint, not by a review."
+ *
+ * This is the lint. The type system already stops a NodeId being treated as a string —
+ * its payload hangs off a module-private symbol — so the only way through is to import
+ * one of seam.ts's three accessors. This test says which files are allowed to.
+ */
+
+import assert from 'node:assert/strict';
+import { readFileSync, readdirSync, statSync } from 'node:fs';
+import { join, relative } from 'node:path';
+import { test } from 'node:test';
+import { fileURLToPath } from 'node:url';
+
+const SRC = fileURLToPath(new URL('../src', import.meta.url));
+
+const sourceFiles = (directory: string): readonly string[] =>
+  readdirSync(directory).flatMap((entry) => {
+    const full = join(directory, entry);
+    if (statSync(full).isDirectory()) return sourceFiles(full);
+    return full.endsWith('.ts') ? [full] : [];
+  });
+
+const importersOf = (accessor: string): readonly string[] =>
+  sourceFiles(SRC)
+    .filter((file) => relative(SRC, file) !== 'seam.ts')
+    .filter((file) => new RegExp(`\\b${accessor}\\b`).test(readFileSync(file, 'utf8')))
+    .map((file) => relative(SRC, file))
+    .sort();
+
+test('only seam-stub.ts may look inside a NodeId', () => {
+  assert.deepEqual(
+    importersOf('unsafeReadNodeIdForTrackAStubOnly'),
+    ['seam-stub.ts'],
+    'a second reader of this accessor is a seam violation: Track B would be parsing Track A identifiers',
+  );
+});
