+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+
+import { generatePartyKeys, partyKeysFromSeed, selfSignedAnchor, signCanonicalBytes, stubAnchorResolver, verifyCanonicalBytes } from '../src/signing.ts';
+
+const bytes = Buffer.from('{"a":1}', 'utf8');
+
+test('a signature verifies over the bytes it was made on', () => {
+  const keys = partyKeysFromSeed('signing-test');
+  assert.deepEqual(verifyCanonicalBytes(bytes, signCanonicalBytes(bytes, keys)), { ok: true });
+});
+
+test('a signature does not verify over different bytes', () => {
+  const keys = partyKeysFromSeed('signing-test');
+  const result = verifyCanonicalBytes(Buffer.from('{"a":2}', 'utf8'), signCanonicalBytes(bytes, keys));
+  assert.equal(result.ok, false);
+});
+
+test('a signature does not verify against a different key', () => {
+  const signature = signCanonicalBytes(bytes, partyKeysFromSeed('one'));
+  const impersonated = { ...signature, keyId: partyKeysFromSeed('two').keyId };
+  assert.equal(verifyCanonicalBytes(bytes, impersonated).ok, false);
+});
+
+test('seeded keys are deterministic and generated keys are not', () => {
+  assert.equal(partyKeysFromSeed('same').keyId, partyKeysFromSeed('same').keyId);
+  assert.notEqual(generatePartyKeys().keyId, generatePartyKeys().keyId);
+});
+
+test('an unresolvable key id fails with a reason rather than throwing', () => {
+  const result = verifyCanonicalBytes(bytes, { alg: 'ed25519-detached-raw', keyId: 'did:web:example.com', signature: 'x' });
+  assert.equal(result.ok, false);
+  assert.ok(!result.ok && result.reason.includes('unresolvable key id'));
+});
+
+test('PLACEHOLDER — the only anchor this testbed can resolve is the self-signed one', () => {
+  const keys = partyKeysFromSeed('anchor-test');
+  const signature = signCanonicalBytes(bytes, keys);
+
+  const resolved = stubAnchorResolver(selfSignedAnchor(keys), signature);
+  assert.deepEqual(resolved, { resolved: true, selfAnchored: true, organization: null });
+
+  for (const kind of ['dns_tls', 'oidc_issuer', 'sigstore_fulcio'] as const) {
+    const result = stubAnchorResolver({ kind, ref: 'https://example.com' }, signature);
+    assert.equal(result.resolved, false, `${kind} has no resolver here, and pretending otherwise would be the lie`);
+  }
+});
+
+test('a self-signed anchor naming a key other than the signer\'s does not resolve', () => {
+  const keys = partyKeysFromSeed('anchor-a');
+  const other = partyKeysFromSeed('anchor-b');
+  assert.equal(stubAnchorResolver(selfSignedAnchor(other), signCanonicalBytes(bytes, keys)).resolved, false);
+});
