+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { test } from 'node:test';
+
+import { AppendOnlyStore, StoreBoundaryError } from '../src/store.ts';
+
+const withStore = (body: (store: AppendOnlyStore, workspace: string) => void): void => {
+  const workspace = mkdtempSync(join(tmpdir(), 'vibehub-store-test-'));
+  try {
+    body(new AppendOnlyStore(join(workspace, 'party')), workspace);
+  } finally {
+    rmSync(workspace, { recursive: true, force: true });
+  }
+};
+
+test('entries append in order and read back', () => {
+  withStore((store) => {
+    store.append('emitted', { a: 1 });
+    store.append('received', { b: 2 });
+    const entries = store.read();
+    assert.equal(entries.length, 2);
+    assert.deepEqual(
+      entries.map((entry) => entry.seq),
+      [0, 1],
+    );
+    assert.equal(entries[0]?.direction, 'emitted');
+  });
+});
+
+test('an empty store reads as empty rather than throwing', () => {
+  withStore((store) => {
+    assert.deepEqual(store.read(), []);
+  });
+});
+
+test('a path that escapes the root via .. is refused', () => {
+  withStore((store) => {
+    assert.throws(() => store.resolveInRoot('../owner-a-store/log.ndjson'), StoreBoundaryError);
+    assert.throws(() => store.resolveInRoot('a/b/../../../outside'), StoreBoundaryError);
+  });
+});
+
+test('an absolute path outside the root is refused', () => {
+  withStore((store, workspace) => {
+    assert.throws(() => store.resolveInRoot(join(workspace, 'owner-a-store', 'log.ndjson')), StoreBoundaryError);
+    assert.throws(() => store.resolveInRoot('/etc/passwd'), StoreBoundaryError);
+  });
+});
+
+test('a path inside the root is allowed', () => {
+  withStore((store) => {
+    assert.ok(store.resolveInRoot('nested/log.ndjson').startsWith(store.root));
+  });
+});
+
+/**
+ * The honest limit, asserted so nobody reads more into the testbed's isolation than it
+ * has. Both parties run as the same uid; the confinement is on this class's code path,
+ * not on the process.
+ */
+test('confinement is structural, not OS-enforced: plain fs still reaches the other root', () => {
+  withStore((store, workspace) => {
+    const otherRoot = join(workspace, 'other-party');
+    const other = new AppendOnlyStore(otherRoot);
+    other.append('emitted', { secret: true });
+    assert.throws(() => store.resolveInRoot(join(otherRoot, 'log.ndjson')), StoreBoundaryError);
+    // ...and yet:
+    assert.doesNotThrow(() => writeFileSync(join(otherRoot, 'poke'), 'same uid, same machine'));
+  });
+});
